//! Zeroclaw route surface plugin.
//!
//! Publishes the Antigravity-facing model and CLI routing contract through
//! `PluginSchema` so the UI can render provider/model controls from D-Bus.

use anyhow::Result;
use async_trait::async_trait;
use op_state::{ApplyResult, Checkpoint, DiffMetadata, PluginCapabilities, StateDiff, StatePlugin};
use op_state_store::PluginSchema;
use serde::{Deserialize, Serialize};
use simd_json::{json, OwnedValue as Value};

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct ZeroclawState {
    pub status: String,
    pub selected_provider: String,
    pub selected_model: String,
    pub transport: Value,
    pub providers: Value,
    pub router: Value,
    pub model_routes: Value,
    pub tools: Value,
    pub config_schema: Value,
    pub ui_surfaces: Value,
    pub structured_output: Value,
}

pub struct ZeroclawPlugin;

impl Default for ZeroclawPlugin {
    fn default() -> Self {
        Self
    }
}

impl ZeroclawPlugin {
    pub fn new() -> Self {
        Self
    }

    fn env_or(key: &str, fallback: &str) -> String {
        std::env::var(key).unwrap_or_else(|_| fallback.to_string())
    }

    pub(crate) fn current_state() -> ZeroclawState {
        // Decoupled from factory: local routing defaults to the on-box gemma4
        // via ollama. gemma4 is also the universal router (see `router` below).
        let selected_provider = Self::env_or("LLM_PROVIDER", "ollama");
        let selected_model = Self::env_or("LLM_MODEL", "gemma4");
        let router_endpoint = Self::env_or("ZEROCLAW_ROUTER_ENDPOINT", "http://localhost:11434");
        let wg_xray_target = Self::env_or("ZEROCLAW_WG_XRAY_TARGET", "wg-xray");
        let grpc_target = Self::env_or("ZEROCLAW_GRPC_TARGET", "http://10.200.0.1:50051");

        ZeroclawState {
            status: "declared".to_string(),
            selected_provider,
            selected_model,
            transport: json!({
                "dbus_object": "/opdbus/v1/plugins/zeroclaw",
                "grpc_target": grpc_target,
                "incus_container": wg_xray_target,
                "browser_surface": "gRPC-Web through op-web",
                "rest_aliases": ["/api/zeroclaw/chat", "/api/llm/chat"],
                // Canonical OSCAL/subid mapping authority — referenced, never copied.
                "policy_source": "/opdbus/v1/plugins/oscal_subid_registry",
            }),
            providers: json!([
                {"id": "factory", "route": "factory", "kind": "orchestrator", "aliases": ["default", "auto"]},
                {"id": "codex", "route": "openai-codex", "kind": "provider", "aliases": ["openai_codex", "codex"]},
                {"id": "ollama", "route": "ollama", "kind": "local", "aliases": ["gemma", "gemma4"]},
                {"id": "antigravity", "route": "antigravity", "kind": "orchestrator", "aliases": ["google.antigravity"]},
                {"id": "google", "route": "gemini", "kind": "provider", "aliases": ["gemini", "google-gemini"]},
                {"id": "opencode", "route": "custom:opencode", "kind": "cli", "aliases": []},
                {"id": "kilocode", "route": "custom:kilocode", "kind": "cli", "aliases": ["kilo-code", "kilo_code"]},
                {"id": "openrouter", "route": "openrouter", "kind": "router", "aliases": []},
                {"id": "anthropic", "route": "anthropic", "kind": "provider", "aliases": []},
                {"id": "openai", "route": "openai", "kind": "provider", "aliases": []},
                {"id": "gemini-cli", "route": "gemini-cli", "kind": "cli", "aliases": []},
                // OSCAL compliance routing: a policy-kind provider (assess, not chat).
                // `source` points at the canonical subid registry — the mapping
                // authority — instead of restating control mappings here.
                {"id": "oscal", "route": "oscal", "kind": "policy", "aliases": ["compliance", "subid", "nist"], "source": "/opdbus/v1/plugins/oscal_subid_registry"}
            ]),
            // gemma4 is the universal router: it classifies EVERY request into a
            // route/tag (provider+model, hint, candidate OSCAL subids). It only
            // emits tags — the deterministic layer (routes below, oscal registry,
            // xray) enforces them. Not just compliance routing.
            router: json!({
                "provider": "ollama",
                "model": "gemma4",
                "endpoint": router_endpoint,
                "scope": "all",
                "role": "context_aware_allocator",
                "emits": ["provider", "model", "hint", "candidate_subids", "confidence", "thinking_budget", "reasoning_effort"],
            }),
            model_routes: json!([
                {
                    "hint": "code",
                    "provider": "openrouter",
                    "upstream_provider": "openrouter",
                    "transport": "direct",
                    "model": "anthropic/claude-sonnet-4.6",
                    "kind": "chat",
                    "status": "declared",
                    "available": false,
                    "status_reason": "Declared route; backend availability must be projected before execution.",
                    "api_key": null
                },
                {
                    "hint": "fast",
                    "provider": "gemini",
                    "upstream_provider": "gemini",
                    "transport": "direct",
                    "model": "gemini-2.5-flash",
                    "kind": "chat",
                    "status": "declared",
                    "available": false,
                    "status_reason": "Declared route; backend availability must be projected before execution.",
                    "api_key": null
                },
                {
                    "hint": "local",
                    "provider": "ollama",
                    "upstream_provider": "ollama",
                    "transport": "loopback",
                    "model": "gemma4",
                    "kind": "router",
                    "status": "declared",
                    "available": false,
                    "status_reason": "gemma4 is the declared local classifier; unavailable until Ollama projects it.",
                    "api_key": null
                },
                // Factory auto-routing: selects best available provider based on query type
                {
                    "hint": "auto",
                    "provider": "factory",
                    "upstream_provider": "factory",
                    "transport": "auto",
                    "model": "auto",
                    "kind": "orchestrator",
                    "status": "declared",
                    "available": true,
                    "status_reason": "Factory auto-router available - selects best provider based on query classification.",
                    "api_key": null
                },
                {
                    "hint": "code",
                    "provider": "factory",
                    "upstream_provider": "openrouter",
                    "transport": "direct",
                    "model": "anthropic/claude-sonnet-4.6",
                    "kind": "chat",
                    "status": "declared",
                    "available": false,
                    "status_reason": "Factory code route -> openrouter/claude; requires backend projection.",
                    "api_key": null
                },
                {
                    "hint": "fast",
                    "provider": "factory",
                    "upstream_provider": "gemini",
                    "transport": "direct",
                    "model": "gemini-2.5-flash",
                    "kind": "chat",
                    "status": "declared",
                    "available": false,
                    "status_reason": "Factory fast route -> gemini/flash; requires backend projection.",
                    "api_key": null
                },
                {
                    "hint": "local",
                    "provider": "factory",
                    "upstream_provider": "ollama",
                    "transport": "loopback",
                    "model": "gemma4",
                    "kind": "router",
                    "status": "declared",
                    "available": false,
                    "status_reason": "Factory local route -> ollama/gemma4; requires backend projection.",
                    "api_key": null
                },
                {
                    "hint": "reasoning",
                    "provider": "factory",
                    "upstream_provider": "antigravity",
                    "transport": "direct",
                    "model": "gemini-3-pro-preview",
                    "kind": "chat",
                    "status": "declared",
                    "available": false,
                    "status_reason": "Factory reasoning route; Gemma dynamically allocates thinking budget.",
                    "api_key": null
                },
                // Compliance baseline routed through the OSCAL policy provider; the
                // model id is a canonical OSCAL profile reference resolved via the
                // subid registry, not an LLM model.
                {
                    "hint": "compliance",
                    "provider": "oscal",
                    "upstream_provider": "oscal",
                    "transport": "dbus",
                    "model": "NIST_SP_800-53_Rev5",
                    "kind": "policy",
                    "status": "declared",
                    "available": false,
                    "status_reason": "OSCAL policy provider is declared; unavailable until oscal_subid_registry is projected.",
                    "source": "/opdbus/v1/plugins/oscal_subid_registry",
                    "api_key": null
                }
            ]),
            tools: json!([
                {
                    "name": "zeroclaw.chat",
                    "description": "Send an Antigravity/Zeroclaw chat turn and return structured JSON when response_schema is present.",
                    "parameters": {
                        "type": "object",
                        "properties": {
                            "message": {"type": "string"},
                            "provider": {"type": "string"},
                            "model": {"type": "string"},
                            "response_schema": {"type": "object"}
                        },
                        "required": ["message"]
                    }
                },
                {
                    "name": "zeroclaw.models.list",
                    "description": "List cached or live models for a Zeroclaw provider.",
                    "parameters": {
                        "type": "object",
                        "properties": {"provider": {"type": "string"}},
                        "required": []
                    }
                }
            ]),
            config_schema: json!({
                "source": "zeroclaw config schema",
                "schema_crate": "schemars",
                "native_type": "zeroclaw::config::schema::Config",
                "status": "available_via_cli_or_gateway"
            }),
            ui_surfaces: json!([
                {"path": "/chat", "name": "Antigravity Chat", "schema": "zeroclaw"},
                {"path": "/grpc", "name": "gRPC Diagnostics", "schema": "plugin-service"},
                {"path": "/models", "name": "Routable Models", "schema": "zeroclaw.providers"}
            ]),
            structured_output: json!({
                "sdk": "google.antigravity",
                "config_object": "LocalAgentConfig(response_schema=UiResponseSchema)",
                "extractor": "response.structured_output()",
                "response_schema": {
                    "action": "",
                    "metadata": {},
                    "confidence_score": 0.0
                },
                "pydantic_source": [
                    "import pydantic",
                    "class UiResponseSchema(pydantic.BaseModel):",
                    "    action: str",
                    "    metadata: dict[str, str]",
                    "    confidence_score: float"
                ],
                "ui_renderer": "JsonRenderer",
                "required": true
            }),
        }
    }
}

#[async_trait]
impl StatePlugin for ZeroclawPlugin {
    fn name(&self) -> &str {
        "zeroclaw"
    }

    fn version(&self) -> &str {
        "1.0.0"
    }

    fn schema(&self) -> Option<PluginSchema> {
        Some(super::plugin_schema_defs::zeroclaw_plugin_schema())
    }

    async fn query_current_state(&self) -> Result<Value> {
        Ok(simd_json::serde::to_owned_value(Self::current_state())?)
    }

    async fn calculate_diff(&self, _current: &Value, _desired: &Value) -> Result<StateDiff> {
        Ok(StateDiff {
            plugin: self.name().to_string(),
            actions: vec![],
            metadata: DiffMetadata {
                timestamp: chrono::Utc::now().timestamp(),
                current_hash: "schema-declared".to_string(),
                desired_hash: "schema-declared".to_string(),
            },
        })
    }

    async fn apply_state(&self, _diff: &StateDiff) -> Result<ApplyResult> {
        Ok(ApplyResult {
            success: true,
            changes_applied: vec![],
            errors: vec![],
            checkpoint: None,
        })
    }

    async fn verify_state(&self, _desired: &Value) -> Result<bool> {
        Ok(true)
    }

    async fn create_checkpoint(&self) -> Result<Checkpoint> {
        Ok(Checkpoint {
            id: uuid::Uuid::new_v4().to_string(),
            plugin: self.name().to_string(),
            timestamp: chrono::Utc::now().timestamp(),
            state_snapshot: simd_json::serde::to_owned_value(Self::current_state())?,
            backend_checkpoint: None,
        })
    }

    async fn rollback(&self, _checkpoint: &Checkpoint) -> Result<()> {
        Ok(())
    }

    fn capabilities(&self) -> PluginCapabilities {
        PluginCapabilities {
            supports_rollback: false,
            supports_checkpoints: true,
            supports_verification: true,
            atomic_operations: false,
        }
    }
}

//! Auto-Discovery and Creation of Plugins
//!
//! This module provides the capability to automatically discover system services
//! and create corresponding state plugins.

use anyhow::{anyhow, Result};
use async_trait::async_trait;
use op_agents::{create_agent, AgentTask};
use op_state::StatePlugin;
use op_state_store::PluginSchema;
use simd_json::prelude::*;
use simd_json::{json, OwnedValue as Value};
use std::collections::HashMap;
use std::sync::Arc;
use tokio::sync::RwLock;

/// Auto-creator for systemd-based plugins
pub struct SystemdAutoCreator;

impl SystemdAutoCreator {
    /// Discover systemd units and create plugins
    pub async fn discover_units() -> Result<Vec<(String, Value)>> {
        let mut plugins = Vec::new();

        // Example discovery: find all active .service units
        // In a real implementation, this would query systemd via D-Bus
        let discovered_units = vec!["nginx.service", "redis.service", "postgresql.service"];

        for unit in discovered_units {
            plugins.push((
                unit.to_string(),
                json!({
                    "type": "systemd",
                    "name": unit,
                    "state": "active",
                    "enabled": true
                }),
            ));
        }

        Ok(plugins)
    }
}

/// Generic auto-plugin that can wrap discovered services
pub struct AutoPlugin {
    name: String,
    _category: String,
    schema: PluginSchema,
    current_state: Arc<RwLock<Value>>,
}

impl AutoPlugin {
    pub fn new(name: &str, category: &str, initial_state: Value) -> Self {
        let schema = Self::build_auto_schema(name, category);
        Self {
            name: name.to_string(),
            _category: category.to_string(),
            schema,
            current_state: Arc::new(RwLock::new(initial_state)),
        }
    }

    pub fn new_with_schema(
        name: &str,
        category: &str,
        initial_state: Value,
        schema: PluginSchema,
    ) -> Self {
        Self {
            name: name.to_string(),
            _category: category.to_string(),
            schema,
            current_state: Arc::new(RwLock::new(initial_state)),
        }
    }

    pub async fn create_from_requested_info(name: &str, requested_info: &str) -> Self {
        let research = match Self::query_elements_via_agent(requested_info).await {
            Ok(value) => value,
            Err(error) => json!({
                "query": requested_info,
                "web_results": [],
                "recommended_fields": [],
                "pending_human_review": true,
                "review_reason": format!("web research unavailable: {}", error),
            }),
        };

        let pending_human_review = research
            .get("pending_human_review")
            .and_then(|v| v.as_bool())
            .unwrap_or(true);
        let review_reason = research
            .get("review_reason")
            .and_then(|v| v.as_str())
            .unwrap_or("Insufficient evidence; human review required.");
        let recommended_fields = research
            .get("recommended_fields")
            .and_then(|v| v.as_array())
            .cloned()
            .unwrap_or_default();
        let web_results_count = research
            .get("web_results")
            .and_then(|v| v.as_array())
            .map(|a| a.len())
            .unwrap_or(0);

        let state = json!({
            "plugin_id": name,
            "requested_info": requested_info,
            "status": if pending_human_review { "draft_pending_review" } else { "draft_researched" },
            "pending_human_review": pending_human_review,
            "review_reason": review_reason,
            "recommended_fields": recommended_fields,
            "research": research,
            "web_results_count": web_results_count,
            "created_at": chrono::Utc::now().to_rfc3339(),
        });

        let schema = Self::build_auto_schema(name, "auto_discovered");
        Self::new_with_schema(name, "auto_discovered", state, schema)
    }

    async fn query_elements_via_agent(requested_info: &str) -> Result<Value> {
        let agent_id = format!("plugin-auto-create-{}", uuid::Uuid::new_v4());
        let agent = create_agent("search-specialist", agent_id)
            .map_err(|e| anyhow!("failed to create search-specialist agent: {}", e))?;

        let args_payload = json!({
            "query": format!(
                "{} required configuration fields plugin schema state model capabilities",
                requested_info
            ),
            "requested": requested_info,
        });
        let args_json = simd_json::to_string(&args_payload)
            .map_err(|e| anyhow!("failed to encode agent args: {}", e))?;
        let task = AgentTask {
            task_type: "search-specialist".to_string(),
            operation: "research_plugin_elements".to_string(),
            path: None,
            args: Some(args_json),
            config: HashMap::new(),
        };

        let result = agent
            .execute(task)
            .await
            .map_err(|e| anyhow!("search-specialist execution failed: {}", e))?;
        if !result.success {
            return Err(anyhow!(
                "search-specialist reported failure: {}",
                result.data
            ));
        }

        let parsed = serde_json::from_str(&result.data)
            .map_err(|e| anyhow!("invalid agent JSON response: {}", e))?;
        Ok(parsed)
    }

    fn build_auto_schema(name: &str, category: &str) -> PluginSchema {
        PluginSchema::builder(name)
            .version("1.0.0")
            .category(category)
            .description("Auto-created plugin draft. Requires human review before production use.")
            .string_field("plugin_id", true, "Canonical plugin identifier")
            .string_field(
                "requested_info",
                true,
                "Original user request for plugin creation",
            )
            .string_field(
                "status",
                true,
                "Lifecycle status of this auto-created draft",
            )
            .boolean_field(
                "pending_human_review",
                true,
                "If true, plugin must be reviewed before activation",
            )
            .string_field(
                "review_reason",
                true,
                "Reason this draft requires human review",
            )
            .array_field(
                "recommended_fields",
                op_state_store::FieldType::String,
                false,
                "Field suggestions gathered from web research",
            )
            .field(
                "research",
                op_state_store::FieldSchema {
                    field_type: op_state_store::FieldType::Any,
                    required: false,
                    description: "Raw research payload from search-specialist agent".to_string(),
                    default: None,
                    example: None,
                    constraints: Vec::new(),
                    read_only: true,
                    read_only_when: None,
                },
            )
            .integer_field(
                "web_results_count",
                false,
                "Count of discovered web results",
            )
            .string_field("created_at", true, "RFC3339 creation timestamp")
            .build()
    }
}

#[async_trait]
impl StatePlugin for AutoPlugin {
    fn name(&self) -> &str {
        &self.name
    }

    fn version(&self) -> &str {
        "1.0.0"
    }

    fn schema(&self) -> Option<PluginSchema> {
        Some(self.schema.clone())
    }

    async fn query_current_state(&self) -> Result<Value> {
        Ok(self.current_state.read().await.clone())
    }

    async fn calculate_diff(
        &self,
        current: &Value,
        desired: &Value,
    ) -> Result<op_state::StateDiff> {
        // Simple generic diff: if not equal, replace
        let mut actions = Vec::new();
        if current != desired {
            actions.push(op_state::StateAction::Create {
                resource: self.name.clone(),
                config: desired.clone(),
            });
        }

        Ok(op_state::StateDiff {
            plugin: self.name.clone(),
            actions,
            metadata: op_state::DiffMetadata {
                timestamp: chrono::Utc::now().timestamp(),
                current_hash: format!("{:x}", md5::compute(simd_json::to_string(current)?)),
                desired_hash: format!("{:x}", md5::compute(simd_json::to_string(desired)?)),
            },
        })
    }

    async fn apply_state(&self, diff: &op_state::StateDiff) -> Result<op_state::ApplyResult> {
        let changes = Vec::new();
        let errors = Vec::new();

        for action in &diff.actions {
            if let op_state::StateAction::Create { config, .. } = action {
                let mut state = self.current_state.write().await;
                *state = config.clone();
            }
        }

        Ok(op_state::ApplyResult {
            success: true,
            changes_applied: changes,
            errors,
            checkpoint: None,
        })
    }

    async fn verify_state(&self, desired: &Value) -> Result<bool> {
        let current = self.current_state.read().await;
        Ok(*current == desired)
    }

    async fn create_checkpoint(&self) -> Result<op_state::Checkpoint> {
        let state = self.current_state.read().await;
        Ok(op_state::Checkpoint {
            id: uuid::Uuid::new_v4().to_string(),
            plugin: self.name.clone(),
            timestamp: chrono::Utc::now().timestamp(),
            state_snapshot: state.clone(),
            backend_checkpoint: None,
        })
    }

    async fn rollback(&self, checkpoint: &op_state::Checkpoint) -> Result<()> {
        let mut state = self.current_state.write().await;
        *state = checkpoint.state_snapshot.clone();
        Ok(())
    }

    fn capabilities(&self) -> op_state::PluginCapabilities {
        op_state::PluginCapabilities {
            supports_rollback: true,
            supports_checkpoints: true,
            supports_verification: true,
            atomic_operations: true,
        }
    }
}

[package]
name = "op-llm"
version.workspace = true
edition.workspace = true
authors.workspace = true
